
  // ==========================================================================
  // SOUND MANAGER — signature sonore originale BLEDOO
  // Un seul son sur tout le site : joué une unique fois, au moment précis où
  // la commande part vers WhatsApp (voir sendOrder()). Toutes les autres
  // interactions (clic, ajout panier, suppression, erreur, notifications...)
  // restent silencieuses, volontairement, pour que ce son de confirmation de
  // commande reste net et distinctif plutôt que noyé parmi d'autres sons.
  // C'est un petit fichier audio MP3 (quelques Ko), composé spécifiquement
  // pour ce site — aucun son copié d'une autre application, aucune
  // ressemblance avec WhatsApp. Embarqué en base64 directement ici pour que
  // le site reste un fichier HTML unique, autonome, sans requête réseau
  // supplémentaire ni délai de chargement.
  //
  // Remplacer ce son plus tard : régénérer le petit fichier mp3 souhaité et
  // remplacer sa valeur dans SOUND_SOURCES ci-dessous — rien d'autre à changer
  // dans le reste du code du site.
  //
  // API : soundManager.play("success")  (joué uniquement dans sendOrder())
  //       soundManager.toggleMute() / soundManager.setMuted(bool) / soundManager.isMuted()
  //       soundManager.setVolume(0..1) / soundManager.getVolume()
  // ==========================================================================
  const soundManager = (function(){
    const STORAGE_KEY = 'bledoo_sound_muted';
    const VOLUME_KEY = 'bledoo_sound_volume';
    const DEFAULT_VOLUME = 0.55; // reste discret, ne surprend pas l'utilisateur

    let muted = false;
    try { muted = localStorage.getItem(STORAGE_KEY) === '1'; } catch(e){ /* stockage indisponible : son activé par défaut */ }

    let volume = DEFAULT_VOLUME;
    try {
      const savedVol = parseFloat(localStorage.getItem(VOLUME_KEY));
      if(!isNaN(savedVol) && savedVol >= 0 && savedVol <= 1) volume = savedVol;
    } catch(e){ /* stockage indisponible : volume par défaut */ }

    // Petit fichier MP3 original (mono, 22.05kHz, ~5 Ko), encodé en base64.
    const SOUND_SOURCES = {
      success: "data:audio/mpeg;base64,"
    };

    const players = {}; // <audio> préchargés, un par son

    // Précharge tous les sons dès le chargement du script (aucun son n'est joué
    // ici : precharger un <audio> ne déclenche pas la lecture, donc aucune
    // règle anti-autoplay n'est concernée par cette étape).
    function preload(){
      Object.keys(SOUND_SOURCES).forEach(function(name){
        try {
          const audio = new Audio(SOUND_SOURCES[name]);
          audio.preload = 'auto';
          audio.volume = volume;
          audio.addEventListener('error', function(){
            // Fichier audio invalide/indisponible pour une raison quelconque :
            // on le désactive proprement, play() deviendra silencieux pour ce son.
            players[name] = null;
          });
          audio.load();
          players[name] = audio;
        } catch(e){
          players[name] = null; // Audio indisponible sur ce navigateur -> fallback silencieux
        }
      });
    }
    preload();

    // Ne jamais superposer deux sons : coupe tout ce qui est en cours avant de jouer.
    function stopAll(){
      Object.keys(players).forEach(function(name){
        const a = players[name];
        if(a && !a.paused){
          try { a.pause(); a.currentTime = 0; } catch(e){}
        }
      });
    }

    function play(name){
      if(muted) return;
      const audio = players[name];
      if(!audio) return; // son inconnu ou indisponible -> fallback silencieux, le site reste utilisable
      stopAll();
      try {
        audio.currentTime = 0;
        const p = audio.play();
        if(p && typeof p.catch === 'function'){
          p.catch(function(){ /* lecture bloquée (ex: politique autoplay du navigateur) -> ignoré silencieusement */ });
        }
      } catch(e){
        // Échec ponctuel de lecture -> fallback silencieux
      }
    }

    function updateToggleUI(){
      const btn = document.getElementById('soundToggle');
      if(!btn) return;
      btn.innerHTML = muted ? ICONS.soundOff : ICONS.soundOn;
      // t() est défini plus loin dans le script ; à l'appel initial (DOMContentLoaded)
      // il est déjà disponible, donc on l'utilise s'il existe pour un libellé traduit.
      const raw = muted ? 'Activer les sons' : 'Couper les sons';
      const label = (typeof window.t === 'function') ? window.t(raw) : raw;
      btn.setAttribute('aria-label', label);
      btn.title = label;
    }

    function setMuted(value){
      muted = !!value;
      try { localStorage.setItem(STORAGE_KEY, muted ? '1' : '0'); } catch(e){ /* mémorisation best-effort */ }
      updateToggleUI();
    }

    function toggleMute(){
      setMuted(!muted);
    }

    function setVolume(value, opts){
      let v = parseFloat(value);
      if(isNaN(v)) return;
      v = Math.max(0, Math.min(1, v));
      volume = v;
      try { localStorage.setItem(VOLUME_KEY, String(volume)); } catch(e){ /* mémorisation best-effort */ }
      Object.keys(players).forEach(function(name){
        const a = players[name];
        if(a) a.volume = volume;
      });
    }

    function getVolume(){ return volume; }

    if(document.readyState === 'loading'){
      document.addEventListener('DOMContentLoaded', updateToggleUI);
    } else {
      updateToggleUI();
    }

    return { play: play, toggleMute: toggleMute, setMuted: setMuted, isMuted: function(){ return muted; }, setVolume: setVolume, getVolume: getVolume, refreshLabel: updateToggleUI };
  })();
