  const LANG_KEY = 'bledoo_lang';
  let currentLanguage = 'fr';
  try {
    const savedLang = localStorage.getItem(LANG_KEY);
    if(savedLang === 'en' || savedLang === 'fr') currentLanguage = savedLang;
  } catch(e){ /* stockage indisponible : français par défaut */ }

  function t(str){
    if(currentLanguage === 'en' && Object.prototype.hasOwnProperty.call(EN_TRANSLATIONS, str)){
      return EN_TRANSLATIONS[str];
    }
    return str;
  }

  function applyStaticTranslations(){
    document.querySelectorAll('[data-i18n]').forEach(function(el){
      const key = el.getAttribute('data-i18n');
      el.innerHTML = t(key);
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el){
      const key = el.getAttribute('data-i18n-placeholder');
      el.setAttribute('placeholder', t(key));
    });
    document.querySelectorAll('[data-i18n-aria]').forEach(function(el){
      const key = el.getAttribute('data-i18n-aria');
      el.setAttribute('aria-label', t(key));
    });
    document.querySelectorAll('[data-i18n-title]').forEach(function(el){
      const key = el.getAttribute('data-i18n-title');
      el.setAttribute('title', t(key));
    });
    document.documentElement.setAttribute('lang', currentLanguage === 'en' ? 'en' : 'fr');
    if(typeof soundManager !== 'undefined' && soundManager.refreshLabel) soundManager.refreshLabel();
  }

  function applyLanguageUI(lang){
    const frBtn = document.getElementById('langBtnFr');
    const enBtn = document.getElementById('langBtnEn');
    if(frBtn && enBtn){
      frBtn.classList.toggle('active', lang !== 'en');
      enBtn.classList.toggle('active', lang === 'en');
    }
  }

  function setLanguage(lang){
    lang = (lang === 'en') ? 'en' : 'fr';
    currentLanguage = lang;
    try { localStorage.setItem(LANG_KEY, lang); } catch(e){ /* mémorisation best-effort */ }
    applyLanguageUI(lang);
    applyStaticTranslations();
    // Re-rend la vue actuellement affichée pour que le nouveau texte s'applique
    // partout (cartes plats, packs, panier), sans changer la vue en cours.
    if(document.getElementById('products') && document.getElementById('products').style.display === 'block'){
      renderProducts();
    } else if(document.getElementById('formatChoiceSection') && document.getElementById('formatChoiceSection').style.display === 'block'){
      renderFormatChoice();
    } else {
      filterDishes();
    }
    renderCart();
    renderHeroPhoto();
  }

  // ---------- LIVRAISON ----------
  const DELIVERY_FEE = 1000;
  const FREE_ZONES = ["Akwa", "Bonabéri", "Bonamoussadi", "Deido", "Bonanjo", "Bonapriso", "Makepe", "Logpom", "Logbessou", "Ndokoti", "Kotto", "Bali", "Nkongmondo", "Bépanda", "Newbel", "Mboppi"];

  function normalizeText(s){
    return s.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
  }

  function isFreeZone(quartier){
    const norm = normalizeText(quartier);
    if(!norm) return null;
    return FREE_ZONES.some(z => norm.includes(normalizeText(z)));
  }

  let lastFreeZoneState = null; // évite de rejouer le son à chaque frappe clavier
  function updateDeliveryFeeNote(){
    const quartier = document.getElementById('custQuartier').value.trim();
    const note = document.getElementById('quartierFeeNote');
    const display = document.getElementById('deliveryFeeValue');
    const free = isFreeZone(quartier);

    if(free === null){
      note.textContent = '';
      note.className = 'quartier-fee-note';
      display.textContent = t('Entrez votre quartier ci-dessous');
    } else if(free){
      note.textContent = t('Livraison gratuite pour ') + quartier + t(' !');
      note.className = 'quartier-fee-note free';
      display.textContent = t('Gratuite');
    } else {
      note.textContent = t('Frais de livraison pour ') + quartier + t(' : ') + fmt(DELIVERY_FEE) + t('.');
      note.className = 'quartier-fee-note paid';
      display.textContent = fmt(DELIVERY_FEE);
    }
    lastFreeZoneState = free;
  }

  // Photos réelles des packs Ndolé (à afficher sur les cartes de packs)
  const NDOLE_PACK_PHOTO_1 = "data:image/webp;base64,";
  const NDOLE_PACK_PHOTO_2 = "data:image/webp;base64,";
  const OKOK_PACK_PHOTO_1 = "data:image/webp;base64,";
  const ERU_PACK_PHOTO_1 = "data:image/webp;base64,";

  function fmt(n){
    return n.toLocaleString('fr-FR') + " FCFA";
  }

  function waLink(message, number){
    return `https://wa.me/${number || WHATSAPP_NUMBER}?text=${encodeURIComponent(message)}`;
  }

